// Memory writes route by kind with policies attached (plain JS)
const memory = { episodic: [], semantic: new Map(), working: {} };
function remember(kind, key, value, meta = {}) {
  if (kind === "episodic") memory.episodic.push({ key, value, at: Date.now(), ...meta });
  if (kind === "semantic") memory.semantic.set(key, { value, at: Date.now(), version: (memory.semantic.get(key)?.version || 0) + 1 });
  if (kind === "working") memory.working[key] = value; // bounded elsewhere (Ch.2)
}
// Episodes append (history), facts upsert with versions (contradictions explicit),
// working overwrites within budgets. Kinds never mix.

// Decay sweep: prune by age/importance with logs (plain JS)
function decay(memory, now, maxAgeMs, minImportance) {
  const pruned = [];
  memory.episodic = memory.episodic.filter((e) => {
    const keep = now - e.at < maxAgeMs || (e.importance || 0) >= minImportance;
    if (!keep) pruned.push(e.key);
    return keep;
  });
  return { kept: memory.episodic.length, pruned };
}
// Importance floors protect VIP facts; everything else ages out loudly (logged).

