const memory = { episodic: [], semantic: new Map() };
function remember(kind, key, value, meta) {
  meta = meta || {};
  if (kind === 'episodic') memory.episodic.push({ key, value, at: meta.at || 0, importance: meta.importance || 0 });
  if (kind === 'semantic') memory.semantic.set(key, { value, version: (memory.semantic.get(key) || { version: 0 }).version + 1 });
}
function decay(now, maxAge, minImp) {
  const kept = memory.episodic.filter((e) => now - e.at < maxAge || e.importance >= minImp);
  const pruned = memory.episodic.length - kept.length;
  memory.episodic = kept;
  return { kept: kept.length, pruned };
}
